   268|  if (area === 'render' && signal.deployFailed === true) return 'critical';
   269|  if (area === 'supabase' && signal.reachable === false) return 'critical';
   270|  if (area === 'api' && Number(signal.errorRate ?? 0) >= 0.25) return 'critical';
   271|  if (area === 'api' && Number(signal.errorRate ?? 0) >= 0.10) return 'high';
   272|  if (area === 'latency' && Number(signal.p95Ms ?? 0) >= 5000) return 'high';
   273|  if (area === 'queue' && Number(signal.failureRate ?? 0) >= 0.20) return 'high';
   274|  return 'medium';
