   282|      return `Render deploy ${snapshot.render.latestDeployId ?? '?'} status=${renderStatus} on commit ${recentSha}. Likely cause: build/deploy failure or service suspension.`;
   283|    case 'render':
   284|      return `Render API/service unhealthy. configured=${snapshot.render.configured}, error=${snapshot.render.error ?? 'none'}.`;
