   570|// ---------- Confidence + deploy gates ----------
   571|
   572|/**
   573| * Compute a confidence score in [0, 1] for an upcoming deploy/patch.
   574| * Lower = riskier. Combines: open critical incidents, recent failed
   575| * fixes, telemetry error rate, and snapshot health.
   576| */
   577|export async function computeDeployConfidence(): Promise<{ confidence: number; signals: DeployGateDecision['signals'] }> {
   578|  const [incidents, fixes, telemetry, snapshot] = await Promise.all([
   579|    listIncidents(40),
   580|    listFixOutcomes(40),
   581|    getTelemetryStats(60),
   582|    getOperationalSnapshot(),
   583|  ]);
   584|  const openIncidents = incidents.length;
   585|  const criticalIncidents = incidents.filter((i) => i.severity === 'critical' || i.severity === 'high').length;
   586|  const recentFailedFixes = fixes.filter((f) => f.outcome === 'failed' || f.outcome === 'rolled_back').length;
   587|  const snapshotOk = snapshot.supabase.reachable && snapshot.render.ok !== false;
   588|  const telemetryErrorRate = telemetry.errorRate;
   589|
   590|  let score = 1;
   591|  score -= Math.min(0.4, criticalIncidents * 0.15);
   592|  score -= Math.min(0.2, openIncidents * 0.02);
   593|  score -= Math.min(0.2, recentFailedFixes * 0.05);
   594|  score -= Math.min(0.3, telemetryErrorRate * 1.5);
   595|  if (!snapshotOk) score -= 0.2;
   596|  score = Math.max(0, Math.min(1, score));
   597|
   598|  return {
   599|    confidence: Number(score.toFixed(3)),
   600|    signals: { openIncidents, criticalIncidents, recentFailedFixes, snapshotOk, telemetryErrorRate },
   601|  };
   602|}
   603|
   604|export async function evaluateDeployGate(): Promise<DeployGateDecision> {
   605|  const { confidence, signals } = await computeDeployConfidence();
   606|  const reasons: string[] = [];
   607|  let riskLevel: DeployRiskLevel;
   608|  let action: DeployGateDecision['action'];
   609|
   610|  if (signals.criticalIncidents > 0 || confidence < 0.4) {
   611|    riskLevel = 'high';
   612|    action = 'blocked';
   613|    reasons.push(`High risk: critical=${signals.criticalIncidents}, confidence=${confidence}.`);
   614|  } else if (confidence < 0.75 || signals.openIncidents > 0 || signals.telemetryErrorRate > 0.05) {
   615|    riskLevel = 'medium';
   616|    action = 'require_owner_approval';
   617|    reasons.push(`Medium risk: confidence=${confidence}, openIncidents=${signals.openIncidents}.`);
   618|  } else {
   619|    riskLevel = 'low';
   620|    action = 'auto_deploy';
   621|    reasons.push(`Low risk: confidence=${confidence}, no open incidents.`);
   622|  }
   623|
   624|  const decision: DeployGateDecision = {
   625|    riskLevel,
   626|    confidence,
   627|    action,
   628|    reasons,
   629|    signals,
   630|    decidedAt: nowIso(),
   631|    marker: OPERATIONAL_MEMORY_MARKER,
   632|  };
   633|
   634|  await recordDecision({
   635|    kind: 'gate',
   636|    title: `deploy_gate:${riskLevel}:${action}`,
   637|    reason: reasons.join(' '),
   638|    outcome: action === 'blocked' ? 'blocked' : action === 'auto_deploy' ? 'success' : 'pending',
   639|    metadata: { ...decision },
   640|  });
   641|
   642|  return decision;
   643|}
